import shlex, re

def handle(query, state):
    vfs = state.get("files", {})

    def run_cmd(argv):
        if not argv:
            return ""
        cmd, args = argv[0], argv[1:]
        if cmd == "nslookup":
            host = args[-1] if args else ""
            if re.search(r'[;|`&$]', host):
                return "nslookup: invalid character in host\n"
            return (
                f"Server:\t\t127.0.0.53\nAddress:\t127.0.0.53#53\n\n"
                f"Non-authoritative answer:\nName:\t{host}\nAddress: 93.184.216.34\n"
            )
        elif cmd == "cat":
            out = ""
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f"cat: {path}: No such file or directory\n"
                else:
                    out += content
                    if not content.endswith("\n"):
                        out += "\n"
            return out
        elif cmd == "echo":
            import re as _re
            def arith_expand(s):
                def repl(m):
                    try:
                        return str(eval(m.group(1), {"__builtins__": {}}))
                    except Exception:
                        return m.group(0)
                return _re.sub(r'\$\(\(([^)]+)\)\)', repl, s)
            return " ".join(arith_expand(a) for a in args) + "\n"
        elif cmd == "ls":
            entries = sorted(vfs.keys())
            return "\n".join(entries) + "\n" if entries else ""
        elif cmd == "id":
            return "uid=1000(www-data) gid=1000(www-data) groups=1000(www-data)\n"
        else:
            return f"{cmd}: command not found\n"

    def shell_exec(cmdline):
        output = ""
        for segment in cmdline.split(";"):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment)
            except ValueError:
                argv = segment.split()
            output += run_cmd(argv)
        return output

    domain = (query.get("domain") or [""])[0]
    if not domain:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?domain=<hostname>\n"

    output = shell_exec("nslookup " + domain)
    return 200, {"Content-Type": "text/plain"}, output
